#!/bin/bash
# Disposable: milestone 5 on an AUSTIN gfx942 node (no shared home, its own /cluster),
# adapted from megakernels qwen3.6-35b-a3b-gfx942/scripts/suite_austin.sh. One srun step
# in the hipdnn gfx942 image. Everything lives in node-local /tmp: HOME (MIOpen needs a
# writable one), venv, models from HF, the megakernels clone at REV. It runs
# scratch/m3/plans/final.sh with local one/two helpers and prints the logs as a base64
# tar between RESULTS-BEGIN / RESULTS-END.
set -uo pipefail
main() {
REV=${REV:-57d6a48}
echo "SLURM_JOB_ID=$SLURM_JOB_ID node $(hostname -s) $(date -Is)"
df -h /tmp | tail -1
rocminfo | grep -m1 -oE 'gfx[0-9a-f]+'; rocm-smi --showproductname 2>/dev/null | grep -m2 "Card Series"
W=/tmp/mk38_$SLURM_JOB_ID
mkdir -p "$W" && cd "$W" || exit 1
trap 'rm -rf "$W"' EXIT
export HOME=$W PIP_CACHE_DIR=$W/pipcache HF_HOME=$W/hf FLYDSL_RUNTIME_ENABLE_CACHE=0
git clone -q -b users/sareeder/qwen38-tp2 https://github.com/SamuelReeder/megakernels.git src && git -C src checkout -q "$REV" || exit 1
S=$W/src/qwen3.8-27b-gfx942
MK_ENV=$W/mk/venv bash $S/scripts/setup_env.sh || exit 1
. "$W/mk/venv/bin/activate"
M=$W/mk/models
hf download amd/Qwen3.8-27B-Quark-AWQ-MXFP4 --local-dir $M/Qwen3.8-27B-Quark-AWQ-MXFP4 > /dev/null &
hf download Qwen/Qwen3.8-27B --local-dir $M/Qwen3.8-27B > /dev/null &
wait
echo "models $(date -Is)"
echo  | base64 -d > $M/Qwen3.8-27B-Quark-AWQ-MXFP4/config.json
echo "safetensors sizes (expected, then here):"
echo  | base64 -d | md5sum
(cd $M && du -b Qwen3.8-27B-Quark-AWQ-MXFP4/*.safetensors Qwen3.8-27B/*.safetensors | sort -k2 | tr "\t" " " | md5sum)
OUT=$W/out; mkdir -p $OUT
MX=$M/Qwen3.8-27B-Quark-AWQ-MXFP4 BF=$M/Qwen3.8-27B PORT=29600
one() { local name=$1 gpu=$2; shift 2
  SLURM_PROCID=0 bash $S/scratch/m3/task.sh $OUT $name HIP_VISIBLE_DEVICES=$gpu "$@" & }
two() { local name=$1; shift; PORT=$((PORT + 1))
  for r in 0 1; do SLURM_PROCID=$r SLURM_NTASKS=2 bash $S/scratch/m3/task.sh $OUT $name MK_TP=2 MK_PORT=$PORT "$@" & done
  wait; }
echo "plan start $(date -Is)"
. $S/scratch/m3/plans/final.sh
wait
echo "plan done $(date -Is)"
cat $OUT/status.log
echo RESULTS-BEGIN
tar -C $W -czf - out | base64
echo RESULTS-END
}
main < /dev/null
exit
